-- Private retention data and controlled, auditable rewards. Programme starts disabled.
create table public.saved_social_profiles(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,label text not null check(char_length(label) between 1 and 80),platform text not null check(platform in('instagram','youtube','facebook','linkedin','telegram','tiktok','x')),public_url text not null check(public_url ~ '^https?://'),note text check(char_length(note)<=500),last_used_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,platform,public_url));
create table public.customer_favourites(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,service_id bigint not null references public.services(id) on delete cascade,created_at timestamptz not null default now(),unique(user_id,service_id));
create table public.reward_programme_rules(id boolean primary key default true check(id),enabled boolean not null default false,manual_approval boolean not null default true,minimum_order_amount numeric(14,2) not null default 0 check(minimum_order_amount>=0),referrer_reward numeric(14,2) not null default 0 check(referrer_reward>=0),new_customer_reward numeric(14,2) not null default 0 check(new_customer_reward>=0),referral_expiry_days integer not null default 30 check(referral_expiry_days between 1 and 365),loyalty_spend_threshold numeric(14,2),loyalty_reward numeric(14,2),updated_by uuid references auth.users(id),updated_at timestamptz not null default now());insert into public.reward_programme_rules(id) values(true) on conflict do nothing;
create table public.referral_codes(id uuid primary key default gen_random_uuid(),user_id uuid not null unique references auth.users(id) on delete cascade,code text not null unique check(code ~ '^[A-Z0-9]{8,16}$'),created_at timestamptz not null default now());
create table public.referral_attributions(id uuid primary key default gen_random_uuid(),referrer_id uuid not null references auth.users(id),referred_user_id uuid not null unique references auth.users(id),referral_code_id uuid not null references public.referral_codes(id),status text not null default 'pending' check(status in('pending','qualified','rewarded','rejected','reversed','expired')),qualifying_order_id uuid unique references public.orders(id),expires_at timestamptz not null,qualified_at timestamptz,rewarded_at timestamptz,internal_risk_note text,created_at timestamptz not null default now(),check(referrer_id<>referred_user_id));
create table public.customer_reward_events(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id),event_type text not null check(event_type in('referral_reward','loyalty_reward','promotional_credit','reward_reversal')),referral_id uuid references public.referral_attributions(id),qualifying_order_id uuid references public.orders(id),amount numeric(14,2) not null check(amount>0),status text not null default 'pending' check(status in('pending','approved','credited','rejected','reversed')),transaction_id uuid unique references public.transactions(id),source text not null default 'admin',internal_note text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(event_type,user_id,qualifying_order_id));
alter table public.saved_social_profiles enable row level security;alter table public.customer_favourites enable row level security;alter table public.reward_programme_rules enable row level security;alter table public.referral_codes enable row level security;alter table public.referral_attributions enable row level security;alter table public.customer_reward_events enable row level security;
create policy saved_owner_all on public.saved_social_profiles for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create policy favourites_owner_all on public.customer_favourites for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy rules_admin_all on public.reward_programme_rules for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy rules_customer_read on public.reward_programme_rules for select to authenticated using(true);
create policy codes_owner_read on public.referral_codes for select to authenticated using(user_id=auth.uid() or public.is_admin());create policy attributions_related_read on public.referral_attributions for select to authenticated using(referrer_id=auth.uid() or referred_user_id=auth.uid() or public.is_admin());create policy rewards_owner_read on public.customer_reward_events for select to authenticated using(user_id=auth.uid() or public.is_admin());create policy rewards_admin_all on public.customer_reward_events for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy attributions_admin_all on public.referral_attributions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create or replace function public.ensure_my_referral_code() returns text language plpgsql security definer set search_path=public as $$declare v text;begin if auth.uid() is null then raise exception 'Authentication required';end if;select code into v from referral_codes where user_id=auth.uid();if v is null then v='SR'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));insert into referral_codes(user_id,code)values(auth.uid(),v);end if;return v;end$$;revoke all on function public.ensure_my_referral_code() from public;grant execute on function public.ensure_my_referral_code() to authenticated;
create or replace function public.admin_credit_reward(p_event uuid) returns uuid language plpgsql security definer set search_path=public as $$declare e customer_reward_events%rowtype;o orders%rowtype;t uuid;r reward_programme_rules%rowtype;begin if not public.is_admin() then raise exception 'Admin required';end if;select * into e from customer_reward_events where id=p_event for update;if e.status='credited' then return e.transaction_id;end if;select * into r from reward_programme_rules where id=true;if not r.enabled then raise exception 'Programme disabled';end if;select * into o from orders where id=e.qualifying_order_id for update;if o.id is null or o.user_id is distinct from(case when e.event_type='referral_reward' then (select referred_user_id from referral_attributions where id=e.referral_id) else e.user_id end) or o.status<>'completed' or coalesce(o.payment_status,'paid') not in('paid','completed') or o.charge<r.minimum_order_amount then raise exception 'Order is not qualifying';end if;if exists(select 1 from transactions where metadata->>'reward_event_id'=e.id::text and status='completed')then select id into t from transactions where metadata->>'reward_event_id'=e.id::text and status='completed';return t;end if;update profiles set balance=balance+e.amount where id=e.user_id;insert into transactions(user_id,amount,type,status,payment_method,description,metadata)values(e.user_id,e.amount,'reward','completed','reward',replace(initcap(replace(e.event_type,'_',' ')),' Reward Reward',' Reward'),jsonb_build_object('reward_event_id',e.id,'qualifying_order_id',e.qualifying_order_id))returning id into t;update customer_reward_events set status='credited',transaction_id=t,updated_at=now() where id=e.id;update referral_attributions set status='rewarded',rewarded_at=now() where id=e.referral_id;return t;end$$;revoke all on function public.admin_credit_reward(uuid) from public;grant execute on function public.admin_credit_reward(uuid) to authenticated;
create index saved_profiles_recent_idx on public.saved_social_profiles(user_id,last_used_at desc nulls last);create index referral_status_idx on public.referral_attributions(status,created_at desc);create index reward_events_user_idx on public.customer_reward_events(user_id,created_at desc);
